class BrebornApp {
  constructor() {
    this.leads = [];
    this.statuses = JSON.parse(localStorage.getItem('breborn_leads_status') || '{}');
    this.notes = JSON.parse(localStorage.getItem('breborn_leads_notes') || '{}');
    this.activePitchLead = null;

    this.initDOM();
    this.initTheme();
    this.initData();
    this.bindEvents();
  }

  initDOM() {
    this.kpiTotal = document.getElementById('kpiTotal');
    this.kpiWa = document.getElementById('kpiWa');
    this.kpiSinWeb = document.getElementById('kpiSinWeb');
    this.kpiContactados = document.getElementById('kpiContactados');

    this.searchInput = document.getElementById('searchInput');
    this.clearSearchBtn = document.getElementById('clearSearch');
    this.categoryFilter = document.getElementById('categoryFilter');
    this.cityFilter = document.getElementById('cityFilter');
    this.waFilter = document.getElementById('waFilter');
    this.webFilter = document.getElementById('webFilter');
    this.statusFilter = document.getElementById('statusFilter');

    this.leadsList = document.getElementById('leadsList');
    this.noResults = document.getElementById('noResults');
    this.resultsCount = document.getElementById('resultsCount');

    this.themeToggle = document.getElementById('themeToggle');
    this.exportCsvBtn = document.getElementById('exportCsvBtn');
    this.resetStorageBtn = document.getElementById('resetStorageBtn');

    // Modal
    this.pitchModal = document.getElementById('pitchModal');
    this.modalBizName = document.getElementById('modalBizName');
    this.pitchTextarea = document.getElementById('pitchTextarea');
    this.closeModalBtn = document.getElementById('closeModal');
    this.copyModalPitchBtn = document.getElementById('copyModalPitch');
    this.sendModalWaBtn = document.getElementById('sendModalWa');
  }

  initTheme() {
    const savedTheme = localStorage.getItem('breborn_theme') || 'dark';
    if (savedTheme === 'light') {
      document.body.classList.remove('theme-dark');
      document.body.classList.add('theme-light');
    } else {
      document.body.classList.remove('theme-light');
      document.body.classList.add('theme-dark');
    }
  }

  async initData() {
    // Use embedded leads directly (flawless for file:// and GitHub Pages)
    this.leads = [...EMBEDDED_LEADS];

    // Optional background check for live json updates if served via HTTP
    if (window.location.protocol.startsWith('http')) {
      try {
        const res = await fetch('data/breborn_leads.json');
        if (res.ok) {
          const freshData = await res.json();
          if (Array.isArray(freshData) && freshData.length > 0) {
            this.leads = freshData;
          }
        }
      } catch (e) {
        console.log('Usando dataset embebido.');
      }
    }

    // Merge saved local storage status
    this.leads.forEach(l => {
      if (this.statuses[l.id]) {
        l.status = this.statuses[l.id];
      }
      if (this.notes[l.id]) {
        l.notes = this.notes[l.id];
      }
    });

    this.render();
  }

  bindEvents() {
    this.searchInput.addEventListener('input', () => {
      this.clearSearchBtn.style.display = this.searchInput.value ? 'block' : 'none';
      this.render();
    });

    this.clearSearchBtn.addEventListener('click', () => {
      this.searchInput.value = '';
      this.clearSearchBtn.style.display = 'none';
      this.render();
    });

    this.categoryFilter.addEventListener('change', () => this.render());
    this.cityFilter.addEventListener('change', () => this.render());
    this.waFilter.addEventListener('change', () => this.render());
    this.webFilter.addEventListener('change', () => this.render());
    this.statusFilter.addEventListener('change', () => this.render());

    this.themeToggle.addEventListener('click', () => {
      const isLight = document.body.classList.contains('theme-light');
      if (isLight) {
        document.body.classList.remove('theme-light');
        document.body.classList.add('theme-dark');
        localStorage.setItem('breborn_theme', 'dark');
      } else {
        document.body.classList.remove('theme-dark');
        document.body.classList.add('theme-light');
        localStorage.setItem('breborn_theme', 'light');
      }
    });

    this.exportCsvBtn.addEventListener('click', () => this.exportCsv());
    this.resetStorageBtn.addEventListener('click', () => {
      if (confirm('¿Deseas reiniciar todos los estados y notas guardadas a "Nuevo"?')) {
        localStorage.removeItem('breborn_leads_status');
        localStorage.removeItem('breborn_leads_notes');
        this.statuses = {};
        this.notes = {};
        this.leads.forEach(l => { l.status = 'Nuevo'; l.notes = ''; });
        this.render();
      }
    });

    // Modal events
    this.closeModalBtn.addEventListener('click', () => this.closeModal());
    this.pitchModal.addEventListener('click', (e) => {
      if (e.target === this.pitchModal) this.closeModal();
    });

    this.copyModalPitchBtn.addEventListener('click', () => {
      navigator.clipboard.writeText(this.pitchTextarea.value).then(() => {
        this.copyModalPitchBtn.textContent = '✓ Copiado al portapapeles!';
        setTimeout(() => {
          this.copyModalPitchBtn.textContent = '📋 Copiar Texto';
        }, 2000);
      });
    });
  }

  getFilteredLeads() {
    const query = this.searchInput.value.toLowerCase().trim();
    const cat = this.categoryFilter.value;
    const city = this.cityFilter.value;
    const wa = this.waFilter.value;
    const web = this.webFilter.value;
    const status = this.statusFilter.value;

    return this.leads.filter(lead => {
      if (query) {
        const text = `${lead.name} ${lead.address} ${lead.category} ${lead.city} ${lead.phone}`.toLowerCase();
        if (!text.includes(query)) return false;
      }

      if (cat !== 'ALL' && lead.category !== cat) return false;
      if (city !== 'ALL' && lead.city !== city) return false;

      if (wa === 'WA_ONLY' && !lead.has_whatsapp) return false;
      if (wa === 'NO_WA' && lead.has_whatsapp) return false;

      if (web === 'NO_WEB' && lead.has_website) return false;
      if (web === 'HAS_WEB' && !lead.has_website) return false;

      if (status !== 'ALL' && lead.status !== status) return false;

      return true;
    });
  }

  updateKPIs() {
    const total = this.leads.length;
    const waCount = this.leads.filter(l => l.has_whatsapp).length;
    const sinWebCount = this.leads.filter(l => !l.has_website).length;
    const contactados = this.leads.filter(l => l.status !== 'Nuevo').length;

    this.kpiTotal.textContent = total;
    this.kpiWa.textContent = waCount;
    this.kpiSinWeb.textContent = sinWebCount;
    this.kpiContactados.textContent = contactados;
  }

  render() {
    this.updateKPIs();
    const filtered = this.getFilteredLeads();

    this.resultsCount.textContent = `Mostrando ${filtered.length} locales (${filtered.filter(l => l.has_whatsapp).length} con WhatsApp directo)`;

    if (filtered.length === 0) {
      this.leadsList.innerHTML = '';
      this.noResults.style.display = 'block';
      return;
    }

    this.noResults.style.display = 'none';
    this.leadsList.innerHTML = filtered.map(lead => this.createLeadCardHTML(lead)).join('');

    // Attach card event listeners
    filtered.forEach(lead => {
      const cardEl = document.getElementById(lead.id);
      if (!cardEl) return;

      // Status change
      const statusSelect = cardEl.querySelector('.status-select');
      statusSelect.addEventListener('change', (e) => {
        this.updateLeadStatus(lead.id, e.target.value);
      });

      // View pitch
      const viewPitchBtn = cardEl.querySelector('.btn-view-pitch');
      if (viewPitchBtn) {
        viewPitchBtn.addEventListener('click', () => this.openPitchModal(lead));
      }

      // WhatsApp direct click
      const waBtn = cardEl.querySelector('.btn-whatsapp');
      if (waBtn) {
        waBtn.addEventListener('click', () => {
          if (lead.status === 'Nuevo') {
            this.updateLeadStatus(lead.id, 'Mensaje Enviado');
          }
        });
      }
    });
  }

  createLeadCardHTML(lead) {
    const isGold = lead.has_whatsapp && !lead.has_website;
    const statusClass = `status-${lead.status.toLowerCase().replace(/\s+/g, '-')}`;

    const catEmoji = {
      'Peluquería y Belleza': '💇',
      'Cafetería': '☕',
      'Pastelería y Panadería': '🥐',
      'Local de Comida / Restaurante': '🍔',
      'Comercio, Ropa y Tiendas': '🛍️'
    }[lead.category] || '🏢';

    return `
      <div id="${lead.id}" class="lead-card ${isGold ? 'gold-lead' : ''}">
        <div class="lead-card-header">
          <div class="lead-title-area">
            <h3 class="lead-title">${lead.name}</h3>
            <div class="lead-badges">
              <span class="badge badge-category">${catEmoji} ${lead.category}</span>
              <span class="badge badge-city">📍 ${lead.city}</span>
              ${
                !lead.has_website
                  ? '<span class="badge badge-noweb">🔥 Sin Web</span>'
                  : `<a href="${lead.website}" target="_blank" rel="noopener" class="badge badge-hasweb">🌐 Ver Web</a>`
              }
            </div>
          </div>
        </div>

        <div class="lead-body">
          <div class="lead-info-row">
            <span class="icon">📍</span>
            <span>${lead.address || 'Viña del Mar / Valparaíso'}</span>
          </div>
          <div class="lead-info-row">
            <span class="icon">${lead.has_whatsapp ? '💬' : '📞'}</span>
            <span class="lead-phone-text">${lead.phone || 'Sin teléfono público registrado'}</span>
          </div>
        </div>

        <div class="lead-status-row">
          <span class="status-label">Estado:</span>
          <select class="status-select ${statusClass}">
            <option value="Nuevo" ${lead.status === 'Nuevo' ? 'selected' : ''}>⚪ Nuevo</option>
            <option value="Mensaje Enviado" ${lead.status === 'Mensaje Enviado' ? 'selected' : ''}>💬 Mensaje Enviado</option>
            <option value="Interesado" ${lead.status === 'Interesado' ? 'selected' : ''}>⭐ Interesado</option>
            <option value="En el Bucle" ${lead.status === 'En el Bucle' ? 'selected' : ''}>🎉 En el Bucle</option>
            <option value="No Interesado" ${lead.status === 'No Interesado' ? 'selected' : ''}>❌ No Interesado</option>
          </select>
        </div>

        <div class="lead-actions">
          <button class="btn btn-secondary btn-view-pitch" title="Ver o editar el pitch para este local">
            📋 Pitch
          </button>
          ${
            lead.has_whatsapp
              ? `<a href="${lead.wa_url}" target="_blank" rel="noopener" class="btn btn-whatsapp" title="Abrir chat en WhatsApp con pitch listo">
                  💬 Enviar WhatsApp
                 </a>`
              : `<button class="btn btn-outline" disabled title="No tiene WhatsApp móvil (+569)">
                  Sin WhatsApp
                 </button>`
          }
        </div>
      </div>
    `;
  }

  updateLeadStatus(leadId, newStatus) {
    this.statuses[leadId] = newStatus;
    localStorage.setItem('breborn_leads_status', JSON.stringify(this.statuses));
    const target = this.leads.find(l => l.id === leadId);
    if (target) target.status = newStatus;
    this.render();
  }

  openPitchModal(lead) {
    this.activePitchLead = lead;
    this.modalBizName.textContent = `Pitch para: ${lead.name} (${lead.city})`;
    this.pitchTextarea.value = lead.pitch;

    if (lead.has_whatsapp) {
      this.sendModalWaBtn.style.display = 'inline-flex';
      this.sendModalWaBtn.href = `https://wa.me/${lead.whatsapp}?text=${encodeURIComponent(lead.pitch)}`;
      this.sendModalWaBtn.onclick = () => {
        if (lead.status === 'Nuevo') {
          this.updateLeadStatus(lead.id, 'Mensaje Enviado');
        }
      };
    } else {
      this.sendModalWaBtn.style.display = 'none';
    }

    this.pitchModal.style.display = 'flex';
  }

  closeModal() {
    this.pitchModal.style.display = 'none';
    this.activePitchLead = null;
  }

  exportCsv() {
    const filtered = this.getFilteredLeads();
    const headers = ["ID", "Nombre", "Categoria", "Comuna", "Direccion", "Telefono", "WhatsApp", "Tiene WhatsApp", "Sitio Web", "Tiene Web", "Estado", "Mensaje Pitch"];
    
    const rows = filtered.map(l => [
      `"${l.id}"`,
      `"${l.name.replace(/"/g, '""')}"`,
      `"${l.category}"`,
      `"${l.city}"`,
      `"${(l.address || '').replace(/"/g, '""')}"`,
      `"${l.phone || ''}"`,
      `"${l.whatsapp || ''}"`,
      `"${l.has_whatsapp ? 'SI' : 'NO'}"`,
      `"${l.website || ''}"`,
      `"${l.has_website ? 'SI' : 'NO'}"`,
      `"${l.status}"`,
      `"${l.pitch.replace(/"/g, '""').replace(/\n/g, ' ')}"`
    ]);

    const csvContent = "\uFEFF" + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `breborn_leads_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }
}

// Initialize on DOM ready
document.addEventListener('DOMContentLoaded', () => {
  window.app = new BrebornApp();
});
